def main():
    data = sys.stdin.read().split()
    H = int(data[0]); W = int(data[1]); K = int(data[2])
    grid = data[3:3+H]
    idx = lambda i, j: i * W + j
    empty = [[grid[i][j] == '.' for j in range(W)] for i in range(H)]
    nbrs = [[] for _ in range(H * W)]
    for i in range(H):
        for j in range(W):
            if not empty[i][j]:
                continue
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i + di, j + dj
                if 0 <= ni < H and 0 <= nj < W and empty[ni][nj]:
                    nbrs[idx(i, j)].append(idx(ni, nj))
    states = defaultdict(int)
    for i in range(H):
        for j in range(W):
            if empty[i][j]:
                c = idx(i, j)
                states[(c, 1 << c)] += 1
    for _ in range(K):
        new = defaultdict(int)
        for (c, mask), cnt in states.items():
            for nb in nbrs[c]:
                if not (mask >> nb) & 1:
                    new[(nb, mask | (1 << nb))] += cnt
        states = new
    print(sum(states.values()))

